    def matdet(matrix):
        """Compute determinant over MOD via Gaussian elimination."""
        m = len(matrix)
        matrix = [row[:] for row in matrix]
        det = 1
        for col in range(m):
            pivot = col
            while pivot < m and matrix[pivot][col] % MOD == 0:
                pivot += 1
            if pivot == m:
                return 0
            if pivot != col:
                matrix[col], matrix[pivot] = matrix[pivot], matrix[col]
                det = (MOD - det) % MOD
            det = (det * matrix[col][col]) % MOD
            inv = pow(matrix[col][col], MOD - 2, MOD)
            for row in range(col + 1, m):
                if matrix[row][col] % MOD != 0:
                    factor = (matrix[row][col] * inv) % MOD
                    for j in range(col, m):
                        matrix[row][j] = (matrix[row][j] - factor * matrix[col][j]) % MOD
