                if not top_ok:
                    continue
                bottom_ok = all(matrix[r + s - 1][cc] == '1' for cc in range(c, c + s))
                if not bottom_ok:
                    continue
                left_ok = all(matrix[rr][c] == '1' for rr in range(r, r + s))
