                    interior_ok = True
                    for rr in range(r + 1, r + s - 1):
                        for cc in range(c + 1, c + s - 1):
                            if matrix[rr][cc] == '1':
                                interior_ok = False
                                break
                        if not interior_ok:
                            break
                    if not interior_ok:
                        continue

                # Check no foreign 1s touch (8-neighbor check on exterior band)
                exterior_ok = True
                for rr in range(r - 1, r + s + 1):
                    for cc in range(c - 1, c + s + 1):
                        if (rr, cc) not in ones:
                            continue
                        # Check if this 1 would touch the square
                        touches = (r - 1 <= rr <= r + s or c - 1 <= cc <= c + s) and \
                                 not (r <= rr < r + s and c <= cc < c + s)
                        if touches:
                            exterior_ok = False
                            break
                    if not exterior_ok:
                        break
                if not exterior_ok:
                    continue

                count += 1

    # Diagonal squares (diamonds)
    for r_center in range(n):
        for c_center in range(m):
            # Check possible radii (Manhattan distance from center)
            max_k = min(r_center, n - 1 - r_center, c_center, m - 1 - c_center)
            for k in range(1, max_k + 1):
                # Diamond frame at Manhattan distance k
                corners = [
                    (r_center - k, c_center),
