def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    if m == n - 1:
        return ""

    orig_edges = []
    for i in range(1, m + 1):
        a, b, e = map(int, lines[i].split())
        orig_edges.append((i - 1, e, a - 1, b - 1))

    # Kruskal's algorithm to build MST
    sorted_edges = sorted(enumerate(orig_edges, 1), key=lambda x: x[1][1])

    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def get_root(x):
        return find(x)

    mst_indices = set()
    for _, (orig_idx, e, u, v) in sorted_edges:
        root_u = get_root(u)
        root_v = get_root(v)
        if root_u != root_v:
            if size[root_u] < size[root_v]:
                root_u, root_v = root_v, root_u
            parent[root_v] = root_u
            size[root_u] += size[root_v]
            mst_indices.add(orig_idx)

    # Build adjacency list for MST
    mst_adj = [[] for _ in range(n + 1)]
    for i, (orig_idx, e, u, v) in enumerate(orig_edges):
        if orig_idx in mst_indices:
            mst_adj[u].append((e, v))
            mst_adj[v].append((e, u))

    # Binary lifting preprocessing
    LOG = 20
    depth = [0] * (n + 1)
    up = [[-1] * LOG for _ in range(n + 1)]
    edge_above = [[float('inf')] * LOG for _ in range(n + 1)]
    visited = [False] * (n + 1)

    # Iterative DFS
    stack = [(1, 0, -1, float('inf'))]
    while stack:
        u, d, p, w = stack.pop()
        if visited[u]:
            continue
        visited[u] = True
        depth[u] = d
        up[u][0] = p
        edge_above[u][0] = w

        for i in range(1, LOG):
            if up[u][i-1] != -1:
                mid = up[u][i-1]
                up[u][i] = up[mid][i-1]
                edge_above[u][i] = min(edge_above[u][i-1], edge_above[mid][i-1])

        for e2, v in mst_adj[u]:
            if v != p and not visited[v]:
                stack.append((v, d + 1, u, e2))

    def get_path_min(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        res = float('inf')

        if depth[u] > depth[v]:
            for j in range(LOG - 1, -1, -1):
                if depth[u] > depth[v] + (1 << j):
                    res = min(res, edge_above[u][j])
                    u = up[u][j]

        if u == v:
            return res

        for j in range(LOG - 1, -1, -1):
            if up[u][j] != up[v][j]:
                res = min(res, edge_above[u][j])
                res = min(res, edge_above[v][j])
                u = up[u][j]
                v = up[v][j]

        res = min(res, edge_above[u][0])
        res = min(res, edge_above[v][0])
        return res

    result = []
    for orig_idx, e, u, v in orig_edges:
        if orig_idx not in mst_indices:
            path_min = get_path_min(u, v)
            result.append(str(path_min))

    return '\n'.join(result)

