        return True

    # Check if consecutive ratios are consistent using cross-multiplication
    # For a GP: seq[i] = seq[i-1] * r, where r = seq[1]/seq[0]
    # Cross-multiply to avoid floating point: seq[i+1] * seq[0] == seq[i] * seq[i]
