        a, b = int(parts[0]), int(parts[1])
        adj[a].append(b)
        adj[b].append(a)

    cycles = []
    visited = [False] * (n + 1)
    parent_arr = [0] * (n + 1)
    discovery = [0] * (n + 1)
    timer = [0]

    def dfs(u):
        visited[u] = True
        discovery[u] = timer[0]
        timer[0] += 1

        for v in adj[u]:
            if not visited[v]:
                parent_arr[v] = u
                dfs(v)
            elif v != parent_arr[u] and discovery[v] < discovery[u]:
                # Back edge found - cycle detected
                path = []
                curr = u
                while curr != v:
                    path.append(curr)
                    curr = parent_arr[curr]
                path.append(v)
                cycle_len = len(path)
