    @lru_cache(maxsize=None)
    def dp(num):
        if num == 0:
            return 0

        digits = set(str(num))
        available = [int(d) for d in digits if d > '0']

        if not available:
            # Only 0s available, this would loop - shouldn't happen for positive num
            return num

        min_ops = float('inf')
        for d in available:
            next_num = num - d
            if next_num >= 0:
                min_ops = min(min_ops, 1 + dp(next_num))

        return min_ops if min_ops != float('inf') else num

    result = dp(n)
    return f'{result}\n'

