    for i in range(1, n + 1):
        parts = lines[i].split()
        centers.append((float(parts[0]), float(parts[1])))

    if n < 3:
        return '-1\n'

    def hyp(i, j):
        return math.hypot(centers[i][0] - centers[j][0], centers[i][1] - centers[j][1])

    max_time = 0.0

    # Check all triplets of circles
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                d1 = hyp(i, j)
                d2 = hyp(i, k)
                d3 = hyp(j, k)

                # Check strict triangle inequality (valid non-degenerate triangle)
                if d1 + d2 > d3 and d1 + d3 > d2 and d2 + d3 > d1:
                    # Time to close this hole = max edge / 2
                    time_for_triangle = max(d1, d2, d3) / 2
                    max_time = max(max_time, time_for_triangle)

    # If no triangle found or max_time == 0, no hole exists
    if max_time == 0.0:
        return '-1\n'

    return f'{max_time:.6f}\n'

