def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        edges.append((int(a) - 1, int(b) - 1))

    # Check if edges (a,b) and (c,d) cross (endpoints interleave)
    def do_cross(e1, e2):
        a, b = e1
        c, d = e2

        # Sort endpoints for consistent comparison
        if a > b:
            a, b = b, a
        if c > d:
            c, d = d, c

        # Two edges cross if one endpoint of e2 is strictly inside (a,b) and the other is outside
        return (a < c < b) ^ (a < d < b)

    # Build conflict graph where edge i and j conflict if they cross
    conflict = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if do_cross(edges[i], edges[j]):
                conflict[i].append(j)
                conflict[j].append(i)

    # Check if the conflict graph is bipartite (2-colorable)
    color = {}
    possible = True

    for i in range(m):
        if i not in color:
            color[i] = 0
            queue = deque([i])
            while queue and possible:
                u = queue.popleft()
                for v in conflict[u]:
                    if v not in color:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        possible = False
                        break

    if not possible:
        return "Impossible"

    # Generate output: color 0 = inside (i), color 1 = outside (o)
    result = ''.join('i' if color[i] == 0 else 'o' for i in range(m)) + '\n'
    return result

