    lines = input_str.strip().split('\n')
    if not lines:
        return "0"

    first_line = lines[0].split()
    n = int(first_line[0])
    m = int(first_line[1])

    attempts = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        attempts.append((parts[0], int(parts[1])))

    count = 0

    # Precompute target arrays for efficiency
    target_arrays = []
    targets = []
    try:
        for s, c in attempts:
            target_arrays.append([int(x) for x in s])
            targets.append(c)
    except:
        return "0"

    def backtrack(pos, matches):
        nonlocal count
        # Early pruning: check if remaining positions can satisfy requirements
        if pos == n:
            if all(matches[i] == targets[i] for i in range(m)):
                count += 1
            return

        # Try both 0 and 1 for current position
        for bit in [0, 1]:
            new_matches = matches[:]
            for i in range(m):
                if target_arrays[i][pos] == bit:
                    new_matches[i] += 1

            # Optional pruning: check if still possible to satisfy all constraints
            # This prevents exploring impossible branches
            possible = True
            for i in range(m):
                if new_matches[i] > targets[i]:
                    possible = False
                    break
                if target_arrays[i][pos] == bit and targets[i] - new_matches[i] > (n - pos - 1):
                    pass  # Still possible to reach target
                # Additional pruning based on minimum matches needed
            if possible:
                backtrack(pos + 1, new_matches)

    backtrack(0, [0] * m)
    return str(count)

