            matrix.append(list(map(int, lines[idx].split())))
            idx += 1

        ops = lines[idx]
        idx += 1

        for op in ops:
            if op == 'R':
                # Shift columns cyclically right
                for i in range(n):
                    new_row = [matrix[i][(j + n - 1) % n] for j in range(n)]
                    matrix[i] = new_row

            elif op == 'L':
                # Shift columns cyclically left
                for i in range(n):
                    new_row = [matrix[i][(j + 1) % n] for j in range(n)]
                    matrix[i] = new_row

            elif op == 'D':
                # Shift rows cyclically down
                new_mat = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        new_mat[i][j] = matrix[(i + n - 1) % n][j]
                matrix = new_mat

            elif op == 'U':
                # Shift rows cyclically up
                new_mat = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        new_mat[i][j] = matrix[(i + 1) % n][j]
                matrix = new_mat

            elif op == 'I':
                # Inverse each row
                for i in range(n):
                    inv_row = [0] * n
                    for j in range(n):
                        inv_row[matrix[i][j] - 1] = j + 1
                    matrix[i] = inv_row

            elif op == 'C':
                # Inverse each column
                new_mat = [[0] * n for _ in range(n)]
                for j in range(n):
                    inv_col = [0] * n
                    for i in range(n):
                        inv_col[matrix[i][j] - 1] = i + 1
                    for i in range(n):
                        new_mat[i][j] = inv_col[i]
                matrix = new_mat

        case_result = '\n'.join(' '.join(map(str, row)) for row in matrix)
        results.append(case_result + '\n')

    return ''.join(results)

