        from collections import defaultdict, deque
        contact_to_wires = defaultdict(list)
        for i, (x, y) in enumerate(wires):
            contact_to_wires[x].append(i)
            contact_to_wires[y].append(i)

        # Find connected components using BFS
        visited = [False] * n
        components = []

        for wire in range(n):
            if not visited[wire]:
                component = []
                queue = deque([wire])
                visited[wire] = True

                while queue:
                    w = queue.popleft()
                    component.append(w)

                    x, y = wires[w]

                    for s in contact_to_wires[x]:
                        if not visited[s]:
                            visited[s] = True
                            queue.append(s)

                    for s in contact_to_wires[y]:
                        if not visited[s]:
