            for comp in components:
                w = comp[0]
                x, y = original_wires[w]

                # Change first contact point to new_contact
                if x != new_contact:
                    new_x = new_contact
                else:
                    # If x is already new_contact (unlikely), use y
                    new_x = y if y != new_contact else (x + 1)

                if new_x != new_contact:
                    continue

                if x != new_contact:
                    wires[w] = (new_contact, y)
                    changes.append((w + 1, x, new_contact))
                    continue

                # Use second contact instead
                if y != new_contact:
                    wires[w] = new_contact, y
                else:
                    wires[w] = new_contact, 1

            results.append(str(changes_needed))
            for w_idx, old_a, new_b in changes:
                results.append(f"{w_idx} {old_a} {new_b}")

    return '\n'.join(results) + '\n'

