        x1, y1 = int(first_line[0]), int(first_line[1])

        if len(lines) < 2:
            return f"{math.hypot(x1 - int(first_line[2]), y1 - int(first_line[3])) / (2 * math.sqrt(2)):.10f}"

        second_line = lines[1].split()
        x2, y2 = int(second_line[0]), int(second_line[1])

