        circles = []
        for i in range(n):
            parts = lines[3 + i].split()
            circles.append((int(parts[0]), int(parts[1]), int(parts[2])))

        mid_x = (x1 + x2) / 2
        mid_y = (y1 + y2) / 2

        dist12_sq = (x1 - x2)**2 + **(y1 - y2)2
        dist12 = math.sqrt(dist12_sq)

        # Perpendicular bisector direction
        # Vector P1P2 is (x2-x1, y2-y1)
        # Perpendicular is (-(y2-y1), x2-x1) = (y1-y2, x2-x1)
        dir_x = y1 - y2
        dir_y = x2 - x1

        def compute_center(r, side):
            """Compute center for circle with radius r passing through P1 and P2"""
            if 4 * r * r < dist12_sq:
                return None
            # Distance from midpoint to center
            t = math.sqrt(4 * r * r - dist12_sq) / 2
            cx = mid_x + side * (t / dist12) * dir_x
            cy = mid_y + side * (t / dist12) * dir_y
            return (cx, cy)

        def valid_for_circle(center, existing_circle):
            """Check if circle with given center and radius doesn't intersect existing circle"""
            ex, ey, er = existing_circle
            dist = math.hypot(center[0] - ex, center[1] - ey)
            # Valid if: disjoint outside (dist + er >= r) OR one inside other (dist <= |r - er|)
            # Using the equivalently: valid if NOT ( intersection )
            # Intersection condition: |r - er| < dist < r + er
            return dist + er >= r + er or dist <= abs(r - er)

        def check_valid_radius(r):
            """Check if there exists a valid center for radius r"""
            for side in [-1, 1]:
                center = compute_center(r, side)
                if center is not None:
                    is_valid = True
                    for circle in circles:
                        if not valid_for_circle(center, circle):
                            is_valid = False
                            break
                    if is_valid:
                        return True
            return False

        # Binary search for minimum radius
        low = dist12 / 2.0
        high = 2.0e10

        for _ in range(100):
            mid = (low + high) / 2
            if check_valid_radius(mid):
                high = mid
            else:
                low = mid

        return f"{high:.10f}"

    except Exception:
        return "0"

