        parts = lines[offset + i].split()
        rules.append((int(parts[0]) - 1, parts[1], int(parts[2]) - 1, parts[3]))

    s_str = lines[offset + m]
    target = list(s_str)

    def is_vowel(char):
        return types[ord(char) - ord('a')] == 'V'

    def is_valid(word):
        if len(word) != n:
            return True
        for pos1, t1, pos2, t2 in rules:
            t1_is_v = (t1 == 'V')
            t2_is_v = (t2 == 'V')
            w1_is_v = is_vowel(word[pos1])
            if w1_is_v == t1_is_v:
                w2_is_v = is_vowel(word[pos2])
                if w2_is_v != t2_is_v:
                    return False
        return True

    if is_valid(target):
        return ''.join(target)

    # Find the best valid word > s lexicographically
    result = None

    # Backtracking to find smallest valid word >= target
    def backtrack(pos, current_word):
        nonlocal result
        if result is not None:
            return

        if pos == n:
            if is_valid(current_word):
                result = ''.join(current_word)
            return

        # Try to match target[pos] first, but ensure we don't go below target
        for i in range(0, 26):
            c = chr(ord('a') + i)
            new_char = c
            if pos < 26 and pos > 0:
                if current_word[pos-1] < c:
                    # Go below alphabetically, skip
                    continue

            new_word = current_word.copy()
            new_word[pos] = new_char

            # Check if going below target[pos] - we should avoid this
            if pos > 0 and new_char < target[pos]:
                continue

            validation_ok = True
            for p, c_char in enumerate(new_word[:pos+1]):
                for pos1, t1, pos2, t2 in rules:
                    t1_val = (t1 == 'V')
                    t2_val = (t2 == 'V')
                    actual1 = is_vowel(c_char)
                    if actual1 == t1_val and pos2 < n:
                        actual2 = is_vowel(new_word[pos2])
                        if actual2 != t2_val:
                            if pos2 <= pos:
                                validation_ok = False
                                break
            if not validation_ok:
                continue

            if backtrack(pos + 1, new_word):
                return 0
            current_word[pos] = new_char

    current = list(target)
    backtrack(0, current)

    if result is not None:
        return result

    return '-1'

