    # Process each position k
    for k in range(n):
        min_val = a[0] + t
        for i in range(n):
            if x[i] > k:  # bus i can potentially reach position k (which is k+1 in 1-indexing)
                min_val = min(min_val, a[i] + t)
        min_needed[k] = min_val

    # Check if every position has at least one bus able to reach it
    for k in range(n):
        if min_needed[k] == float('inf'):
            return "No\n"

    # Construct strictly increasing b
    b = [0] * n
    b[0] = min_needed[0]
    for k in range(1, n):
        b[k] = max(min_needed[k], b[k-1] + 1)

