        for x in arr:
            rem = x % g
            if rem == 0:
                costs.append(0)
            elif rem <= 1:  # rem == 1 means x can become divisible by decreasing to x-1
                costs.append(b)
            elif rem >= g - 1:  # rem == g-1 means x can become divisible by increasing to x+1
                costs.append(b)
            else:
                return INF  # Cannot make x divisible by g

        # If cost of removing segment is higher or equal to cost of changes, skip removal consideration
        if a >= b:
            return sum(costs)

        # Use sliding window to find best subsegment to remove
        min_total = sum(costs)

        # Try removing segments starting from different positions
        for start in range(n):
