                length = end - start + 1
                benefit = costs_in_removed - a  # Savings from not changing, minus removal cost

                current_savings += benefit
                if current_savings > 0:  # Only update if removal saves cost
                    min_total = min(min_total, min_total - current_savings)

        return min_total

