def solution(input_str):
    n, p, l, r = map(int, input_str.strip().split())

    def comb(n, k, mod):
        if k < 0 or k > n:
            return 0
        if k == 0 or k == n:
            return 1
        if k > n // 2:
            k = n - k

        result = 1
        for i in range(k):
            numerator = result * (n - i) % mod
            result = numerator
            denominator = i + 1
            result = result * pow(denominator, mod - 2, mod) % mod
        return result

    total = 0

    for c in range(n + 1):
        m = n - c

        if m < 0:
            continue

        # y_min = ceil((m - r) / 2), y_max = floor((m - l) / 2)
        y_min = (m - r + 1) // 2
        y_max = (m - l) // 2

        if y_min > y_max:
            continue

        # Sum of [C(m, y) - C(m, y-1)] for y in [y_min, y_max]
        # Telescopes to C(m, y_max) - C(m, y_min - 1)

        term = (comb(m, y_max, p) - comb(m, y_min - 1, p) + p) % p
        ways = (term * comb(n, c, p)) % p
        total = (total + ways) % p

    return str(total)

